<?php
require_once __DIR__ . '/../includes/auth.php'; require_login('admin');
$byType = db()->query("SELECT lt.name, lt.color, COUNT(la.id) AS requests, COALESCE(SUM(CASE WHEN la.status = 'approved' THEN la.days ELSE 0 END), 0) AS approved_days FROM leave_types lt LEFT JOIN leave_applications la ON la.leave_type_id = lt.id GROUP BY lt.id ORDER BY approved_days DESC");
$byDepartment = db()->query("SELECT u.department, COUNT(la.id) AS requests, COALESCE(SUM(CASE WHEN la.status = 'approved' THEN la.days ELSE 0 END), 0) AS approved_days FROM users u LEFT JOIN leave_applications la ON la.user_id = u.id WHERE u.role = 'employee' GROUP BY u.department ORDER BY approved_days DESC");
$pageTitle = 'Reports'; require __DIR__ . '/../includes/header.php';
?><div class="page-content"><div class="detail-heading"><div><span class="eyebrow">Administration / Insights</span><h2>Leave reports</h2><p class="muted mb-0">Understand where time away is being used across the team.</p></div><button class="btn btn-outline-dark" onclick="window.print()">Print report</button></div><div class="content-grid"><section class="panel"><div class="panel-heading"><h3>By leave type</h3></div><table class="table"><thead><tr><th>Leave type</th><th>Requests</th><th>Approved days</th></tr></thead><tbody><?php while ($item = $byType->fetch()): ?><tr><td><strong style="color:<?= e($item['color']) ?>">&#9679; <?= e($item['name']) ?></strong></td><td><?= (int) $item['requests'] ?></td><td><?= e((string) $item['approved_days']) ?></td></tr><?php endwhile; ?></tbody></table></section><section class="panel"><div class="panel-heading"><h3>By department</h3></div><table class="table"><thead><tr><th>Department</th><th>Requests</th><th>Approved days</th></tr></thead><tbody><?php while ($item = $byDepartment->fetch()): ?><tr><td><strong><?= e($item['department']) ?></strong></td><td><?= (int) $item['requests'] ?></td><td><?= e((string) $item['approved_days']) ?></td></tr><?php endwhile; ?></tbody></table></section></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>
